import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = [[int(data[2 + i * c + j]) for j in range(c)] for i in range(r)]
INF = float('inf')
best = [[INF] * c for _ in range(r)]
best[0][0] = 0
changed = True
while changed:
    changed = False
    for i in range(r):
        for j in range(c):
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = i + di, j + dj
                if 0 <= a < r and 0 <= b < c:
                    cand = max(best[a][b], abs(g[a][b] - g[i][j]))
                    if cand < best[i][j]:
                        best[i][j] = cand
                        changed = True
print(best[r - 1][c - 1])

